window.MONSTER_CHUNK_123 = [{"name":"Crystal Ooze","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"ooze","subtypes":["aquatic"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":5,"ac_touch":5,"ac_flat_footed":5,"ac_mods":"-5 Dex, +0 natural","hp":65,"hd":"5d8+40","hdvalue":5,"fort":9,"ref":-4,"will":-4,"defensive_abilities":["transparency"],"immunities":["cold","fire","ooze traits"],"weaknesses":["water dependent"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":30}],"melee":"slam +6 (1d6+4 plus 1d6 acid plus grab plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d6+4 1d6+4"},{"type":"paralysis","details":"3d6 rounds, DC 18"}],"strength":16,"dexterity":1,"constitution":26,"wisdom":1,"charisma":1,"baseatk":3,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":11,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":11}],"sq":[{"type":"transparent"}],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature looks like a quivering puddle of water.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"The digestive acid that covers a crystal ooze dissolves metals and organic material, but not stone. Each slam and constrict attack deals 1d6 additional acid damage. Armor or clothing worn by a creature grappled by a crystal ooze takes the same amount of acid damage unless the wearer succeeds on a DC 20 Reflex saving throw. A wooden or metal weapon that strikes a crystal ooze takes 1d6 acid damage unless the weapon's wielder succeeds on a DC 20 Reflex save. The ooze's touch deals 12 points of acid damage per round to wooden or metal objects, but the ooze must remain in contact with the material for 1 full round in order to deal this damage. The save DCs are Constitution-based."},{"type":"Transparency","kind":"Ex","details":"Due to its lack of vivid coloration, a crystal ooze is difficult to discern from its surroundings in most environments. A DC 15 Perception check is required to notice the ooze. Any creature that fails to notice a crystal ooze and walks into it automatically suffers damage as if struck by the ooze's slam attack and is immediately subject to a grab attempt by the ooze."},{"type":"Water Dependency","kind":"Ex","details":"Crystal oozes can survive out of the water for 1 hour per 4 points of Constitution (after that, see the Drowning rules)."}],"description":"The crystal ooze is an aquatic variety of the gray ooze. It is semitransparent and clear and almost impossible to see in the water. The crystal ooze can grow to a length of up to 8 ft. and a thickness of about 6 inches. A crystal ooze strikes by slamming into its opponents. Paralyzed victims are devoured.","ecology":"","habitat_society":"","credit":"The Crystal Ooze originally appeared in the First Edition module S4 The Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Dark Stalker","cr":4,"xp":1200,"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["dark folk"],"init":4,"senses":[{"type":"see in darkness"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 armor, +4 Dex, +2 natural","hp":39,"hd":"6d8+12","hdvalue":6,"fort":4,"ref":9,"will":13,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"2 short swords +6 (1d6+2/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"detect magic"},{"spell":"fog cloud"}]}],"strength":14,"dexterity":18,"constitution":14,"intelligence":9,"wisdom":11,"charisma":13,"baseatk":4,"cmb":22,"cmb_special":"+4 vs. grapple","cmd":35,"cmd_special":"can't be tripped","feats":[{"feat":"Double Slice"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":8},{"skill":"Sleight of Hand","value":5},{"skill":"Stealth","value":8}],"languages":["Dark Folk"],"sq":[{"type":"poison use"}],"environments":["any underground"],"organizations":["solitary","gang (1 dark stalker and 2-5 dark creepers)","clan (20-80 dark creepers plus 1 dark stalker per 20 dark creepers)"],"treasure":"none","description_visual":"This creature appears as a man-sized humanoid with pallid skin. It is clothed in filthy and tattered robes of blackish-gray. The stench of rotted meat and dung clings to this creature.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Su","details":"When a dark stalker is slain, its body combusts in a flash of white-hot flame. This acts like a fireball that deals 3d6 points of fire damage to all creatures within a 20-foot-radius burst. A DC 15 Reflex save halves this damage. A dark stalker's gear and treasure are unaffected by this explosion. This save is Constitution-based."},{"type":"Poison use","kind":"Ex","details":"Dark stalkers are skilled in the use of poison and never risk accidentally poisoning themselves. Like their diminutive kin, the dark creepers, dark stalkers use black poison on their weapons and generally carry six doses on them. Black Smear-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d2 Str; cure 1 save. The poison DC is Constitution-based."},{"type":"See in Darkness","kind":"Su","details":"A dark stalker can see perfectly in darkness of any kind, including that created by deeper darkness."}],"description":"The strange and mysterious dark stalkers are the undisputed leaders of dark folk society. Deep underground, these creatures dwell in strange villages (some rumors suggest entire cities) built of stone and fungus in remote caverns where they are served and worshiped by their coarser, diminutive kin, the dark creepers. Dark stalkers come to the surface rarely, but when they do it is on a mission, and with a force of creatures such that it never ends well for those they seek to rob or torment. Dark stalkers are tall, frail humanoids with incredibly pale skin. They constantly wear multiple layers of dark cloth and black leather armor, yet unlike their lesser kin, a dark stalker's garb is always clean and spotless. Each dark stalker carries a pair of short swords-they prefer these weapons to all others. Dark stalkers are 6 ft. tall and weigh 100 pounds. In a fight, dark stalkers are not above sacrificing lesser creatures, including dark creepers, to win the day or cover their retreat if things go poorly. They hate well-lit areas and always prefer to fight under the cover of deeper darkness. Dark stalkers rarely fight to the death if it can be avoided, preferring to slip away if things begin to look grim. The origins of the dark stalkers and the dark creepers are shrouded in mystery, made more difficult to decipher by the fact that the dark stalkers don't keep records of their history. Many scholars believe that, just as the drow descended from elves, so too must the dark folk have descended from humanity, their eerie powers and spell-like abilities the result of generation upon generation of devotion to profane and sinister magic. Alas, the truth of the race's history may never be known. Dark Stalker Society Wherever a dark creeper city is located, dark stalkers can be found. They are the leaders of the dark creepers and rule with a strong fist. They are ruthless masters, dominating those lesser than themselves (which includes most dark creepers). In times of labor or war, dark stalkers can be seen standing over their dark creeper forces, directing them with a bellowing voice and threats of death to those that fail in their tasks. Some dark creepers have been observed sacrificing items to a dark stalker as if through worship. Whether the lesser creepers view the dark stalkers as deities, however, is a matter of conjecture.","as_character":[{"description":"Dark stalkers possess racial Hit Dice and may have class levels. Dark Creepers have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +6 Dexterity, +4 Constitution, +2 Wisdom, +4 Charisma. Dark stalkers are powerful and have a commanding presence"},{"type":"Base Speed","value":"A dark stalker's base land speed is 30 ft."},{"type":"Darkvision","value":"Dark stalker can see in darkness out to 60 ft."},{"type":"Racial Hit Dice","value":"Dark stalkers begin play with 6 levels of humanoid, which provides 6d8 HD, a base attack bonus of +4, and base saves of Fort +2, Ref +5, Will +2."},{"type":"Racial Skills","value":"A dark stalker's humanoid levels give it skill points equal to 6 x (2 + Int modifier, minimum 1). Dark stalkers receive a +4 racial bonus on Climb, Perception and Stealth checks."},{"type":"Racial Feats","value":"A dark stalker's humanoid levels give it three feats."},{"type":"AC","value":"Dark stalkers receive a +2 natural armor bonus Spell-like abilities: Dark stalkers can cast deeper darkness, detect magic, and fog cloud at will. Their caster level is equal to their Hit Dice"},{"type":"Special Attacks","value":"Death throes, poison use"},{"type":"Special Qualities","value":"Light blindness, see in darkness"},{"type":"Languages","value":"Dark Stalkers begin play speaking Dark Folk. Dark stalkers with high intelligence may choose from the following bonus languages: Common, Undercommon, Goblin, Orc."}]}],"ecology":"","habitat_society":"","credit":"The Dark Stalker originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission.","gear":"6 doses of black smear poison, leather armor, 2 short swords"},{"name":"Dobie","cr":4,"xp":1200,"alignment":"CN","size":"Medium","type":"fey","init":7,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +3 natural","hp":33,"hd":"6d6+12","hdvalue":6,"fort":4,"ref":8,"will":-1,"dr":"5/cold iron","weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"longsword +4 (1d8+1/19-20)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":16,"constitution":14,"intelligence":12,"wisdom":15,"charisma":15,"baseatk":3,"cmb":-5,"cmd":5,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Bluff","value":11},{"skill":"Craft (any one)","value":7},{"skill":"Diplomacy","value":8},{"skill":"Escape Artist","value":12},{"skill":"Handle Animal","value":5},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":11},{"skill":"Perform (dancing)","value":8},{"skill":"Stealth","value":12}],"languages":["Common","Sylvan"],"sq":[{"type":"size alteration"}],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"standard (longsword)","description_visual":"This sylvan creature resembles a 5-foot tall elf with brownish-tan skin, large pointed ears, and brown eyes.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Size Alteration","kind":"Su","details":"At will as a standard action, a dobie can change its size between Medium and Large. Weapons, armor, and other objects on the dobie's person grow proportionally when it changes sizes (objects revert to normal size one round after a dobie releases them). When a dobie becomes Large, its speed increases to 40 ft., it gains +6 Strength, -2 Dexterity, and +4 Constitution, and takes a -1 size penalty to AC. A dobie can use this ability only in its natural environment. If a dobie leaves its natural environment while enlarged, it immediately reverts to its normal size. Additionally, an enlarged dobie that takes 10 points of fire damage or more from a single fire effect immediately reverts to its normal size. It cannot enlarge itself again for 3 rounds after being hit by a fire effect."}],"description":"Dobies are forest creatures believed by some to be the offspring of a spriggan and a dryad, though most learned sages brush this off as simple folklore. They are generally good-natured creatures and aid good-aligned or neutral creatures in need. Creatures they encounter destroying their forests or slaughtering its denizens are attacked almost immediately without question.\n\nDobies build their homes deep within the forests they protect. Though their homes are generally secluded so prying eyes don't disturb them, they always fashion them in such a way that allows the dobie to keep a watchful eye on its domain at all times. Dobies are solitary creatures; if more than one is encountered they are likely a mated pair. Dobies mate for life.\n\nDobies stand about 5 ft. tall but can alter their size to attain heights of 10 ft. They dress in brightly colored clothes and overcoats of green, brown, red, and tan. Dobies can live to be 600 years old, generally reaching maturity around age 100.\n\nDobies enlarge themselves at the start of combat, seeking to gain any advantage they can over their enemies, attacking with both weapons and spell-like abilities. If the battle is going against a dobie, it uses its summon ability to bring forest creatures to its aid and to cover its escape.","ecology":"","habitat_society":""},{"name":"Domovoi","cr":4,"xp":1200,"alignment":"CE","size":"Small","type":"fey","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+4 Dex, +3 natural, +1 size","hp":26,"hd":"4d6+8 (+4)","hdvalue":4,"fort":3,"ref":8,"will":1,"dr":"5/cold iron","sr":15,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"short sword +7 (1d4+1), bite +2 (1d4) or 2 claws +7 (1d3+1 plus grab), bite +7 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"2d6"},{"type":"telekinesis"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"prestidigitation"}]},{"frequency":"3/day","spells":[{"spell":"heat metal"},{"spell":"sleep"},{"spell":"snare"}]}],"strength":13,"dexterity":18,"constitution":15,"intelligence":11,"wisdom":12,"charisma":13,"baseatk":2,"cmb":1,"cmd":9,"cmd_special":"+4 vs. trip","feats":[{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":14},{"skill":"Craft (any one)","value":7},{"skill":"Escape Artist","value":9},{"skill":"Intimidate","value":5},{"skill":"Perception","value":8},{"skill":"Stealth","value":15}],"languages":["Sylvan","Undercommon"],"sq":[{"type":"knocker spirit"}],"environments":["any underground","any urban"],"organizations":["solitary","gang (2-5)"],"treasure":"standard (short sword)","description_visual":"This small hairy humanoid has pointed ears, a long dirty beard, and wields a short sword in its wicked clawed hands.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Knocker Spirit","kind":"Su","details":"A domovoi killed by violence rises in 1 hour as a poltergeist."},{"type":"Telekinesis","kind":"Su","details":"As a standard action once per turn, a domovoi can use telekinesis. This ability functions as the telekinesis spell with a CL equal to the domovoi's Hit Dice (CL 4th for most domovoi). A typical domovoi has a ranged attack roll of +5 when using telekinesis to hurl objects or creatures, and can use this ability on objects or creatures of up to 75 pounds. If a domovoi attempts to hurl a creature with this ability, that creature can resist the effect with a successful DC 13 Will save. The save DC is Strength-based."}],"description":"Domovoi are wicked fey found at the forests' edge, in underground caves, and in small cities and towns, usually dwelling in ruined buildings or in attics and crawlspaces of occupied residences. They are capricious and violent creatures and take great delight in inflicting harm on those that cross them-and sometimes on those that don't.\n\nDomovoi stand just over 2 ft. tall and weigh around 60 pounds. Their clothes are usually dirty and smelly, but other than that seem to be well kept (no holes, no tears, for example). The creature's hair is dark and wildly unkempt. Males have long dirty beards the same color as their hair. No females or young domovoi have been encountered.\n\nDomovoi prefer to attack from ambush, startling their opponents with sudden attacks and catching them unaware. A favored tactic is to stay hidden and assault a target with random objects through the use of the domovoi's telekinesis.","ecology":"","habitat_society":""},{"name":"Doombat Bat","cr":4,"xp":1200,"alignment":"NE","size":"Large","type":"magical beast","init":5,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darvkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+5 Dex, +3 natural, -1 size","hp":42,"hd":"5d10+15","hdvalue":5,"fort":7,"ref":9,"will":6,"speed":[{"type":"land","speed":10},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"bite +7 (2d6+3), tail lash +2 (1d6+1)","space":"10 ft.","reach":"5 ft. (10 ft. with tail)","special_attacks":[{"type":"shriek"},{"type":"yip"}],"strength":17,"dexterity":21,"constitution":17,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":5,"cmb":8,"cmd":20,"feats":[{"feat":"Stealthy"},{"feat":"Skill Focus (Perception, Stealth)"}],"skills":[{"skill":"Escape Artist","value":7},{"skill":"Fly","value":11},{"skill":"Perception","value":14},{"skill":"Stealth","value":10}],"environments":["any underground"],"organizations":["solitary","colony (2-5)"],"treasure":"none","description_visual":"This creature appears as a giant black bat with glowing yellow eyes.","group":"Bat","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Shriek","kind":"Ex","details":"A doombat can emit a piercing shriek every 1d4 rounds. All creatures that can hear the doombat's shriek (except other doombats) within a 100-ft. radius must succeed on a DC 15 Will save or become shaken for 1d4+1 rounds. Successive shrieks don't stack with each other but do extend the duration of the effect. A creature that successfully saves is immune to the same doombat's shriek for 24 hours. The save DC is Constitution-based."},{"type":"Yip","kind":"Ex","details":"A doombat yips constantly while in combat. The noise interferes with an opponent's ability to focus on difficult tasks. Spellcasters within 100 ft. of a yipping doombat must succeed on a concentration check (DC 15 + spell's level) anytime they attempt to cast a spell. The effect of several doombats yipping at once isn't cumulative."}],"description":"The doombat is a nocturnal hunter that desires living flesh to sustain it.\n\nThe approach of a doombat can be heard long before the creature arrives on the scene, the yipping growing louder as the doombat draws closer.\n\nThe doombat has a 10-ft. wingspan, though specimens with wingspans reaching 25 ft. have been reported.\n\nDoombats attack any living thing they encounter. They enter melee and attack with their vicious bite and tail slash, yipping for the duration of the fight.","ecology":"","habitat_society":"","credit":"The Doombat originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Draug","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"undead","subtypes":["water"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":38,"hd":"5d8+10","hdvalue":5,"fort":5,"ref":3,"will":3,"defensive_abilities":["channel resistance +2"],"immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"cutlass +6 (1d6+2/19-20) or 2 claws +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"call storm"}],"strength":14,"dexterity":15,"intelligence":12,"wisdom":14,"charisma":14,"baseatk":3,"cmb":5,"cmd":15,"feats":[{"feat":"Alertness"},{"feat":"Great Fortitude"},{"feat":"Weapon Focus (cutlass)"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Climb","value":8},{"skill":"Escape Artist","value":5},{"skill":"Perception","value":10},{"skill":"Profession (sailor)","value":6},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":8},{"skill":"Survival","value":5},{"skill":"Swim","value":17}],"sq":[{"type":"control ship"}],"environments":["any"],"organizations":["solitary","crew (1 draug plus 6-11 brine zombies and 1-4 mummies of the deep, 2-8 lacedons, or 2-8 skeletons)"],"treasure":"standard","description_visual":"This ragged humanoid is lean and ravaged by decay with bits of bone showing beneath waterlogged, blue-green rotting flesh. Its clothes hang in tatters and its weapons are pitted and rusted.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Call Storm","kind":"Su","details":"Once per day, a draug can summon inclement weather to harass its opponents. The effects are felt immediately (i.e., there is no gradual shift in the weather). Otherwise, this ability is identical to the control weather spell (caster level 6th)."},{"type":"Control Ship","kind":"Su","details":"A draug has full control over its vessel (wind notwithstanding) so long as it remains at the wheel or within 20 ft. of the helmsman. Should it leave the area, its ship meanders in a random direction until the draug regains control. A draug also imbues its ship with special abilities (see Draug Ships, below)."}],"description":"The draug is the vengeful spirit of a ship's captain who died at sea, thus being denied a proper burial. If an entire ship sinks at sea with the loss of all hands, the ship itself and its entire crew may return as ghostly wanderers. The captain usually rises as a draug and his crew rises as brine zombies (see that entry). A draug looks as it did in life, wearing the same clothes and bearing the same possessions it held at the moment of death. The arrival of a draug is often taken as a death portent, for even if it doesn't attack, some dire circumstance is likely to befall the witness. A draug often acts as a death token, rising out of the sea and staring at or pointing a bony finger at a sailor fated to drown. Draugs are jealous of the living and try to bring death and misfortune to them at every opportunity. They have been known to suddenly appear in a sea mist and climb aboard the ships of the living. A draug's favored form of attack is with its cutlass, though if disarmed it uses its claws to attempt to grapple an opponent, leaping back into the waves in an effort to drown the unfortunate victim. Draug Ships When a ship sinks beneath the waves, it and its entire crew may return as ghostly wanderers, especially if the captain and crew had a less than scrupulous profession (as pirates, for example). A sunken ship of this nature may undergo a transformation from the negative energy and evil surrounding it. When this happens, the ship rises from the deep, piloted by a draug and manned by skeletons, brine zombies, zombies, and lacedons. The ship appears as it did at the time of its demise. The sails are tattered and the decks covered with seaweed. When a draug is at the helm, the \"ghost ship\" gains the following powers: Buoyancy (Su) Regardless of the condition of the hull, a draug-piloted ship remains afloat in any weather conditions. It isn't affected by wind of any type (though the draug can still use the wind to maneuver and sail the ship) and can even sail against gale-force winds. Strong waves may toss the ship about, but will not capsize it as a result. Flight (Su) A draug can maneuver his ship to leave the waves and take to the air as long as the draug remains on board. This functions as fly cast by a sorcerer with a caster level equal to the draug's HD. Immunity to Fire (Ex) A draug ship is so waterlogged and infused with negative energy that it is completely immune to all fire effects.","ecology":"","habitat_society":"","gear":"rusty cutlass"},{"name":"Dust Digger","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+7 natural, -1 size","hp":27,"hd":"5d8+5","hdvalue":5,"fort":2,"ref":1,"will":10,"speed":[{"type":"land","speed":10},{"type":"burrow","speed":10}],"melee":"5 tentacles +8 (1d6+3 plus grab) and bite +8 (2d6+3)","space":"10 ft.","reach":"10 ft. (5 ft. with bite)","special_attacks":[{"type":"sinkhole"},{"type":"swallow whole","details":"1d6+3 plus 1d8 acid damage, AC 13, 10 hp"}],"strength":16,"dexterity":10,"constitution":13,"intelligence":2,"wisdom":11,"charisma":10,"baseatk":3,"cmb":15,"cmd":28,"feats":[{"feat":"Improved Natural Attack (bite)"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":5,"special":"+17 sandy terrain"}],"sq":[{"type":"earth glide"}],"environments":["warm deserts"],"organizations":["solitary","gang (4-8)","colony (9-20)"],"treasure":"none","description_visual":"This creature looks like a man-sized sandy brown starfish with five long tentacles ringing a central maw lined with sharpened teeth and fangs.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A dust digger can glide through sand, loose soil, or other loosely packed earth as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or signs of its presence. A move earth spell cast on an area containing a burrowing dust digger flings the creature back 30 ft., stunning it for 1 round unless it succeeds on a Fortitude save."},{"type":"Sinkhole","kind":"Ex","details":"A buried dust digger can deflate its body as a free action, causing the sand above it to slide toward its maw. A creature standing on a space occupied by a buried dust digger when it deflates is immediately subjected to the dust digger's tentacle attacks."}],"description":"Dust diggers are nocturnal desert carnivores about 10 ft. in diameter.\n\nThe creature spends most of its life buried under sand and dirt, waiting for potential prey to wander too close or actually wander over the area where a dust digger is buried.\n\nA dust digger inflates its body with air, buries itself under a thin lair of sand or dirt, and waits for its prey to pass nearby. When a living creature walks over a dust digger, the creature deflates its body and folds its arms around the victim, attempting to shove the prey into its mouth.","ecology":"","habitat_society":"","credit":"The Dust Digger originally appeared in the First Edition module I3 Pharaoh (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Elven Wasp","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":58,"hd":"9d8+18","hdvalue":9,"fort":8,"ref":5,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"sting +9 (1d6+4 plus poison)","space":"5 ft.","reach":"5 ft.","strength":16,"dexterity":15,"constitution":14,"wisdom":12,"charisma":10,"baseatk":6,"cmb":9,"cmd":21,"skills":[{"skill":"Fly","value":6},{"skill":"Perception","value":9},{"skill":"Stealth","value":6}],"environments":["temperate forests"],"organizations":["solitary","group (2-5)","nest (6-12)"],"treasure":"incidental","description_visual":"This large wasp has a sapphire blue body and jet black wings.","group":"Wasp","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fortitude DC 18; frequency 1/round for 6 rounds; effect 1d4 Dexterity damage; cure 1 save. The save DC is Constitution-based and includes a +2 racial bonus. Non-elves gain a +2 bonus on their Fortitude saves against an elven wasp's poisonous sting."}],"description":"Elven wasps build their lairs deep within the ground in temperate forests, plains, and hills. A rare species is believed to inhabit warm and tropical forests and hills as well. A typical lair is a spiraling tunnel that empties into a large open chamber. The entrance to the lair is usually well-hidden\n\nand difficult to locate (Search DC 20). The wasps also build a special incubating nest nearby (usually within 500 ft. of the main nest); another large spiraling tunnel that empties into a large main chamber. It is in this incubating nest where they store their victims and the female lays her eggs.\n\nElven wasps are hunters; their favorite food being elves. Though not particularly picky with their elven diet, they prefer surface elves to drow or aquatic elves.\n\nElves that fall prey to these wasps are used not only as food, but also as \"incubators\" for the young. A paralyzed elf is dragged back to the wasp's incubating lair and dropped into the main chamber. While still alive and paralyzed, the elf's abdomen is slit open and the female elven wasp lays a single large egg in the wound. The female then leaves the chamber and seals the entrance. In a short time the egg hatches and the elven wasp larvae begin devouring the still living elf. After devouring the majority of the elf, the larvae spin cocoons and pupate, hatching several months later as elven wasps-they then dig their way out of the lair and fly off on their own into the world.\n\nElven wasps are large 6-foot long wasps, though they can grow to be up to 10 ft. in length. Females tend to be slightly larger and more aggressive than males.\n\nAn elven wasp attacks with a vicious stinger that can paralyze its victim. A paralyzed victim, if it's an elf, is dragged back to the wasp's lair where it is used as food and an incubator for the queen's eggs. Non-elf victims are stung to death or left to other predators and scavengers. Some elven wasps, seemingly aware that their paralyzed victims occasionally shake off the effects of their venom, break an elven victim's legs to prevent or hamper any chance a recovered victim has of escaping the lair.","ecology":"","habitat_society":""},{"name":"Emberleaf","cr":4,"xp":1200,"alignment":"N","size":"Small","type":"plant","init":6,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"scent"}],"auras":["heat (10 ft., 1d6 fire)"],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":51,"hd":"6d8+24","hdvalue":6,"fort":9,"ref":4,"will":3,"defensive_abilities":["fire healing"],"immunities":["fire","plant traits"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"2 tendrils +7 (1d6+2 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ring of fire"}],"strength":14,"dexterity":15,"constitution":19,"intelligence":6,"wisdom":12,"charisma":7,"baseatk":4,"cmb":5,"cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":4},{"skill":"Stealth","value":15}],"languages":["Sylvan (can't speak)"],"environments":["temperate forests"],"organizations":["solitary","patch (2-4)"],"treasure":"incidental","description_visual":"This small flowering plant has dark green leaves shot through with crimson. Several small bright yellow flowers are sprinkled around its form.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Fire Healing","kind":"Ex","details":"An emberleaf subjected to fire damage regains 1 hit point for every 3 points of damage the attack would have otherwise dealt."},{"type":"Heat Aura","kind":"Ex","details":"An emberleaf can suppress or restart its heat aura as a free action. If it uses its ring of fire ability, its heat aura automatically dissipates and it cannot restart it again for 1 hour."},{"type":"Ring of Fire","kind":"Su","details":"Once per day as a standard action, an emberleaf can create an immobile, blazing ring of fire in a 30-foot radius around its form. This fire is similar to a wall of fire spell. The ring of fire is 20 ft. tall, and deals 2d6 points of fire damage to creatures within 10 ft. of it. Those beyond 10 ft. but within 20 ft. take 1d6 points of fire damage. Creatures passing through the ring take 3d6 points of fire damage. The ring deals this damage when it appears, and to all creatures in the area on the emberleaf's turn each round. The ring of fire lasts a number of rounds equal to the emberleaf's Hit Dice (6 rounds for a standard emberleaf). The emberleaf cannot use this ability to invoke its fire healing."}],"description":"The emberleaf is a sentient plant found deep within darkened and desolate forests where it preys on insects and other small game animals. Often times, an emberleaf makes its lair near trails or roads that wend their way through the forests in hopes of catching a larger meal passing through.\n\nAn emberleaf appears as a small flowering plant with various yellow, sweet smelling flowers. It typical grows no taller than two or three ft. and when at rest resembles an ordinary plant. The creature is active during the day and rests during the nighttime hours. During warmer months, the creature is more active, while during cooler months and winter, the creature is dormant most of the time. An emberleaf can go up to one month without eating.\n\nEmberleafs don't actively hunt prey. Rather, they wait for their prey to come to them. The sweet smelling flowers and aroma given off by the flowers usually attracts insects and small game who unknowingly wander into range of the emberleaf's tendrils. Particularly tough opponents are subjected to its heat aura. If extremely hungry, an emberleaf uses its ring of fire attack to prevent its prey from escaping.","ecology":"","habitat_society":""},{"name":"Eye Killer","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":45,"hd":"6d10+12","hdvalue":6,"fort":7,"ref":7,"will":2,"weaknesses":["sunlight vulnerability"],"speed":[{"type":"land","speed":30}],"melee":"tail slap +10 (1d8+4 plus grab)","ranged":"eye ray +9 ranged touch (death gaze)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+4"}],"strength":16,"dexterity":14,"constitution":14,"intelligence":2,"wisdom":10,"charisma":12,"baseatk":6,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Natural Attack (tail slap)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (tail slap)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":8}],"environments":["any underground"],"organizations":["solitary","gang (2-5)","pack (5-8)"],"treasure":"none","description_visual":"This man-sized creature looks like a cross between a bat and a snake. Its upper torso resembles that of a large black bat while its lower torso appears to be that of a green and yellow scaled snake. Dark green fur covers its upper body. Its eyes are large, lidless white circles and are without pupils.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Gaze","kind":"Su","details":"By using natural or magical light that illuminates it (meaning the eye killer must be within the radius covered by a natural or magical light source), an eye killer can amplify the light and refocus it in a line that functions as a death ray to a range of 50 ft. The eye killer must make a ranged touch attack against its target as a standard action. If successful, the creature struck must make succeed on a DC 15 Fortitude save or perish. Even if the save succeeds, the victim takes 3d6 points of damage. An eye killer can use this gaze once per day. The save DC is Constitution-based. Eye killers are immune to their own gaze attack and to the gaze attack of other eye killers. If the eye killer's gaze attack is reflected back upon it, it amplifies the intensity and projects it at a new target as an immediate action. The save DC to resist this gaze is increased by +2."},{"type":"Sunlight Vulnerability","kind":"Ex","details":"If natural sunlight (including a daylight spell) is brought within 5 ft. of an eye killer, it immediately releases a grappled foe and attempts to move as far away from the source of light as possible. On subsequent rounds, an eye killer is dazzled as long as it remains within 5 ft. of the light source."}],"description":"Eye killers are subterranean dwellers that hate daylight. They dwell underground in dark places, where very little light can touch their sensitive eyes. They are evil, malicious creatures that delight in killing others, particularly those that wander to close to their lair. Eye killers seem to communicate with each other through a series of low rumbles and growls. They don't speak any known language. Eye killers are limbless spherical things at birth, but take form as they develop, reaching maturity within a year. The average adult eye killer reaches a length of 7 ft. Its bat-like wings are useless, as the eye killer cannot fly. The eye killer is very territorial and attacks any living creature that enters an area currently under its watchful eye. If the intruders a wield light source (magical flame, a lantern, or the like), the eye killer attacks using its eye ray ability by absorbing the light (from the source) into its eyes and releasing it in a bright flash of yellow light at its chosen target; otherwise, it dispatches the trespassers by grappling with its tail and squeezing. Eye killers flee if confronted with bright light, but otherwise are relentless in combat and always fight to the death. Umbral Eye Killer The umbral or shadow eye killer is a variant of the standard eye killer. It uses the statistics above for the standard eye killer with the following additions detailed below. An umbral eye killer is CR 5. Spell-like Abilities 3/day-deeper darkness (20-ft. radius). Caster level 6th. See in Darkness (Su) Umbral eye killers can see perfectly in total darkness, even that created by deeper darkness.","ecology":"","habitat_society":"","credit":"The Eye Killer originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Fire Nymph","cr":4,"xp":1200,"alignment":"CN","size":"Medium","type":"outsider","subtypes":["extraplanar","fire"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 Dex, +1 dodge, +3 natural","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":4,"will":6,"immunities":["fire"],"sr":10,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"masterwork dagger +3 (1d4/19-20 plus burn), slam +2  (1d4)","ranged":"masterwork dagger +4 (1d4/19-20 plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d4, DC 12"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"burning hands"},{"spell":"flame blade"},{"spell":"flaming sphere"},{"spell":"produce flame"}]},{"frequency":"1/day","spells":[{"spell":"fire shield"}]}],"strength":10,"dexterity":13,"constitution":12,"intelligence":16,"wisdom":17,"charisma":19,"baseatk":2,"cmb":2,"cmd":14,"feats":[{"feat":"Dodge"}],"skills":[{"skill":"Bluff","value":9},{"skill":"Diplomacy","value":9},{"skill":"Escape Artist","value":6},{"skill":"Knowledge (nature)","value":8},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":6},{"skill":"Survival","value":8}],"languages":["Common","Ignan"],"environments":["any (Plane of Fire)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature appears as a very attractive and beautiful female with long, flowing fiery-red hair. Her eyes are pale blue and her skin is lightly colored with a cinnamon hint to it.","source":"Tome of Horrors Complete (3pp)","description":"A fire nymph is a very beautiful creature that dwells on the Plane of Fire. It is akin to the nymph and dryad, though its origins obviously lie elsewhere. Fire nymphs rarely visit the Material Plane, though mages are known to request their company on occasion. A fire nymph usually wears translucent robes of white or ash.\n\nFire nymphs avoid combat if at all possible, but if pressed into action they rely on their spell-like abilities and seek escape as soon as possible.","ecology":"","habitat_society":"","gear":"masterwork dagger"},{"name":"Fungus Man King","cr":4,"xp":1200,"race":"giant fungus man","alignment":"N","size":"Medium","type":"plant","init":1,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":45,"hd":"6d8+18","hdvalue":6,"fort":8,"ref":3,"will":5,"dr":"5/slashing or piercing","immunities":["poison","plant traits"],"resists":[{"type":"cold","value":5}],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"slam +5 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spore cloud"}],"strength":10,"dexterity":13,"constitution":17,"intelligence":9,"wisdom":12,"charisma":10,"baseatk":4,"cmb":5,"cmd":15,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Perception","value":12},{"skill":"Stealth","value":5}],"environments":["any underground"],"organizations":["solitary","colony (with 30+ fungus men)"],"treasure":"incidental","description_visual":"These small, non-aggressive plant-men appear to be mobile toadstools, with brightly colored caps, stubby arms and thick, trunk-like legs. They don't speak, but they hold up their hands in a sign of peace or supplication.","group":"Fungus Man","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Spore Cloud","kind":"Ex","details":"Once per round as a standard action, a fungus man can release a cloud of noxious spores. All living creatures within 5 ft. must make a DC 16 Fortitude save or become nauseated for 1d4+1 rounds. The save DC is Constitution-based. This is a poison effect, and once a creature successfully saves it is immune to the spore cloud of that particular fungus man for 24 hours."}],"description":"Fungus men are an extremely peaceful and easy-going race of intelligent plants. They are bipedal, in a squat, humanoid fashion. The fungus men are sexless, and reproduce by means of spore clouds. They lack the appendages for fine manipulation of objects, but are quite dexterous in their own way. The fungus men are fiercely loyal to their fungus man king, and attack immediately if it is threatened.\n\nFungus men don't communicate by verbal means; they have learned to deal with outsiders by using hand gestures and supplicating movements. They communicate with each other by pheromones and spores release.\n\nFungus men cohabitate in enclaves throughout the underdark, farming lichen and mosses to trade with other races for soil and excrement (their sources of food). Some fungus man colonies keep \"domesticated\" giant lizards available to replenish their dung fields and for pack animal uses. Fungus man colonies are not hostile towards each other; neither do they work together in any societal fashion.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Fungus Weird","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"plant","subtypes":["fungus"],"init":7,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 Dex, +4 natural, -1 size","hp":39,"hd":"6d8+12","hdvalue":6,"fort":7,"ref":5,"will":3,"dr":"5/bludgeoning","immunities":["plant traits"],"speed":[{"type":"land","speed":30}],"melee":"bite +7 (1d8+4 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"sleep spores"}],"strength":17,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":12,"charisma":13,"baseatk":4,"cmb":8,"cmb_special":"+4 grapple","cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":12},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":8}],"languages":["Common","Terran","Weirdling"],"sq":[{"type":"camouflage"},{"type":"fungus pool"},{"type":"reform"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This creature appears to be a large serpent formed of fungus, plants, and tangled vines. As it moves toward you, it flicks its vine-like tongue and sways back and forth.","group":"Weird","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"A fungus weird is effectively invisible in its pool until it attacks. It takes a successful DC 20 Spot check to notice a fungus weird in its pool before it attacks. Fungus Pool A fungus weird's \"pool\" isn't a pool at all, but an entanglement of leaves, branches, mosses, funguses, and plants. A typical pool covers a 20-foot radius, and a fungus weird (being bound to its pool) can never leave this area. A creature that enters a fungus weird's pool (on its own or with the aid of the fungus weird) is automatically entangled (as the entangle spell) until it escapes. An entangled creature can break free and move half its normal speed by using a full-round action to make a DC 15 Escape Artist check or a DC 19 Strength check. The check DCs are Constitution-based and the Strength check includes a +4 racial bonus."},{"type":"Sleep Spores","kind":"Ex","details":"Once every 1d4 rounds, as a standard action, a fungus weird can release a puff of greenish-yellow spores in a 10-foot cone. These spores induce sleep (as the sleep spell) if the opponent fails a DC 15 Will save. Unlike the sleep spell, there is no HD limit or maximum HD affected. The save DC is Constitution-based."},{"type":"Reform","kind":"Ex","details":"When reduced to 0 hit points or less, a fungus weird collapses back into its pool. Four rounds later, it reforms at full strength minus any damage taken from fire-based spells and effects."}],"description":"Though this creature resembles other weirds, initial suggestions are that this creature is in fact not related to those creatures at all (since other weirds are extraplanar and this creature seems to be native to the Material Plane). The origin of the fungus weird is shrouded in mystery. Legends hint that this weird was created by an ancient race of druids for less than honorable purposes (the exact purpose is unknown).\n\nA fungus weird's diet consists of flesh and blood (which there never seems to be a shortage of in the Underdark thanks to meddlesome adventurers). Though the creature isn't required to eat that often (and can actually go the entire winter months without requiring any food at all), when it does consume food, it ravenously devours it all, leaving nothing but a mass of bent and broken bones (and any other things, such as gear and equipment).\n\nA fungus weird resembles a 10-foot long snake composed of various hues of plants, vines, mushrooms and other funguses. Two dark splotches function as eyes. A vine-like tongue flicks in and out of its mouth.\n\nA fungus weird is an ambush and opportunity hunter, lying in wait in its pool until its prey comes within range. Once a potential target is close by, the fungus weird springs from its pool and attempts to bite and grab its target. A grabbed opponent is pulled into its pool where it is entangled. A creature that struggles, or any additional creatures assaulting the fungus weird are met with a spray of sleep spores.","ecology":"","habitat_society":""},{"name":"Fye","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["despair (10 ft, DC 15)"],"ac":15,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 deflection, +2 Dex, +0 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":4,"ref":3,"will":6,"defensive_abilities":["incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"incorporeal touch +5 (1d6 plus possession)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"possession"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect thoughts"}]},{"frequency":"1/day","spells":[{"spell":"feeblemind"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"}]}],"dexterity":17,"wisdom":14,"charisma":16,"baseatk":3,"cmb":5,"cmd":18,"skills":[{"skill":"Fly","value":10}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a translucent humanoid whose face is contorted and twisted as if frozen in an eternal scream, though it makes no sound.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Despair","kind":"Su","details":"A fye continually emanates an aura of despair in a 10-foot radius. Any creature within or entering this area must succeed on a DC 15 Will save or take a -2 penalty on attack rolls, saving throws, ability and skill checks, and weapon damage rolls for as long as they remain within the area. A creature that successfully saves is immune to the aura of despair of that fye for one day. The save DC is Charisma-based."},{"type":"Possession","kind":"Su","details":"Once per round by making a successful incorporeal touch attack, a fye can merge its body with a creature on the Material Plane. This ability is similar to a magic jar spell, except that it doesn't require a receptacle. The target can resist the possession by succeeding on a DC 15 Will save. If the save fails, the fye disappears and enters the target's body. The save DC is Charisma-based."}],"description":"When a traumatic event occurs within the vicinity of a temple or other holy place, energy often lingers in the area polluting and contaminating an object or the ground itself. This sometimes leads to the formation of a mindless entity-the fye. A fye has no memories because it was never alive, nor does it feel emotions toward any creature living, dead, or undead. Fye don't communicate nor reason, they simply exist. Though it isn't bound to the area where it was created, a fye rarely moves more than 100 ft. or so away from its \"birthplace\". A fye appears as a translucent humanoid about 6 ft. tall whose lower torso tapers off around the knees into vaporous nothingness. Its face always has the appearance that the creature is screaming or howling though it never utters any sound. A fye usually doesn't enter combat unless it is directly approached or molested. In combat, a fye uses its cause fear spell-like ability against its closest target, followed in the next round by its feeblemind ability. If opponents continue to harass the fye it uses its incorporeal touch and possession ability.","ecology":"","habitat_society":""},{"name":"Gallows Tree Zombie","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"plant","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":33,"hd":"6d8+6","hdvalue":6,"hp_mods":["fast healing 5"],"fort":6,"ref":4,"will":2,"immunities":["plant traits"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +8 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spore cloud"}],"strength":19,"dexterity":15,"constitution":13,"intelligence":4,"wisdom":10,"charisma":1,"baseatk":4,"cmb":8,"cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":8}],"languages":["Common (cannot speak)","empathy with gallows tree"],"sq":[{"type":"tether-vine"}],"environments":["any hills","any marshes","any plains","temperate forests","warm forests"],"organizations":["grove (6-11 plus 1 gallows tree)"],"treasure":"none","description_visual":"This creature is a humanoid with deathly gray-green skin dressed in tattered and torn clothes. Small plants, weeds, and fungi grow on the creature's body. A long, sinewy, greenish-brown noose connects the creature to the massive tree behind it.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Spore Cloud","kind":"Ex","details":"As a free action, once every 1d4 rounds (but no more than three times per day), a gallows tree zombie can breathe a cloud of poisonous, greenish spores in a 5-foot cube directly in front of it. A creature caught in the cloud must succeed on a DC 14 Fortitude save or be slowed (as the slow spell) for 6 rounds. One minute later, the creature must make another Fortitude save (same DC) or take 1d3 points of Strength damage. The save DC is Constitution-based."},{"type":"Tether-Vine","kind":"Ex","details":"A gallows tree zombie is connected to the gallows tree that created it by a long, sinewy vine. This vine can be lengthened to allow the zombie to move up to 100 ft. away from the tree. The vine is AC 19 (touch 12) and has 10 hit points. Harming the vine deals no damage to the gallows tree zombie or the gallows tree, but if severed, does prevent the zombie from using its fast healing ability."},{"type":"Tremorsense","kind":"Ex","details":"Gallows tree zombies can automatically sense the location of anything within 60 ft. that is in contact with the same vegetation the zombie is touching."}],"description":"Gallows tree zombies were once living humanoids slain and devoured by a gallows tree and reborn from the seedlings as a minion of said creature.\n\nThey serve no purpose in life now other than killing or capturing living prey for the gallows tree that created them. These monsters retain small memories of their former lives and these scenes sometimes manifest in the zombie's mind, causing it great anger which it vents on the nearest living creature.\n\nGallows tree zombies appear as humanoid creatures with deathly gray green skin that feels coarse and rough to the touch. A long, sinewy cord of greenish-brown wraps around the zombie's throat and connects it to the gallows tree. Gallows tree zombies show no spark of life in their eyes, but are not completely mindless. They are not undead even though their name suggests otherwise; therefore, they cannot be turned or rebuked.\n\nGallows tree zombies hang motionless from the tree that created them, being lowered to the ground only when a living creature comes within 100 ft. of the gallows tree they are connected to. They are formidable opponents and relentlessly pound their foes with their club-like fists while breathing a cloud of choking spores. The zombies prefer uneven odds that favor them, so ganging up on an individual is the norm in battle.\n\nSlain foes are dragged back to the gallows tree, devoured by the tree, and eventually transformed into a gallows tree zombie to replace any that fell in battle.","ecology":"","habitat_society":""},{"name":"Giant Abyssal Dire Frog","cr":4,"xp":1200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["augmented animal","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+4 Dex, +10 natural, -1 size","hp":58,"hd":"4d8+36","hdvalue":4,"fort":13,"ref":10,"will":4,"resists":[{"type":"ance cold","value":5},{"type":"fire","value":5}],"sr":9,"speed":[{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"bite +10 (1d8+8 plus grab) or tongue +10 touch  (grab)","space":"10 ft.","reach":"10 ft. (20 ft. with tongue)","special_attacks":[{"type":"pull","details":"tongue, 10 ft."},{"type":"smite good","details":"1/day, +4 damage"},{"type":"swallow whole","details":"1d8+8 bludgeoning damage, AC 12, 2 hp"},{"type":"tongue"}],"strength":27,"dexterity":19,"constitution":28,"intelligence":5,"wisdom":16,"charisma":14,"baseatk":3,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":13,"special":"+17 jumping"},{"skill":"Perception","value":8},{"skill":"Stealth","value":4},{"skill":"Swim","value":16}],"languages":["Abyssal"],"environments":["any (Plane of Slime)"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This frog appears to be about 12 ft. long. Its skin is blackish-green and constantly oozes a milky slime from its body.","group":"Frog","source":"Tome of Horrors Complete (3pp)","description":"Giant Abyssal dire frogs come from the Plane of Slime and are wholly evil. They have a demonic aspect to them, with a spiny and usually poisonous hide. Their red eyes flicker with demonic intelligence.","ecology":"","habitat_society":"","credit":"The Giant Abyssal Dire Frog made its d20 debut in the Necromancer Games module D1 Tomb of Abysthor."},{"name":"Giant Dragonfly","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"vermin","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+5 Dex, +3 natural","hp":45,"hd":"7d8+14","hdvalue":7,"fort":7,"ref":7,"will":3,"immunities":["vermin traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"bite +11 (1d10+9)","space":"5 ft.","reach":"5 ft.","strength":23,"dexterity":21,"constitution":14,"wisdom":12,"charisma":6,"baseatk":5,"cmb":11,"cmd":26,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":13}],"environments":["any temperate land","any warm land"],"organizations":["solitary","swarm (2-5)"],"treasure":"none (carapace is worth 1,500 gp intact)","description_visual":"This insect resembles a normal dragonfly but is about 5 ft. long. Its skin glitters beautifully in the sunlight, belying the danger that the creature represents.","group":"Dragonfly","source":"Tome of Horrors Complete (3pp)","description":"Giant dragonflies appear as normal dragonflies about 5 ft. long. Their skin, if it can be removed and preserved, brings a very good price on the market. Giant dragonflies are dangerous predators and hunt humans and other humanoids as prey.\n\nA giant dragonfly is very aggressive and hunts warm-blooded creatures fearlessly. It attacks until either it or its prey is dead.","ecology":"","habitat_society":"","credit":"The Giant Dragonfly originally appeared the First Edition module EX2 The Land Beyond the Magic Mirror (© TSR/Wizards of the Coast, 1983) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Giant Pike","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"animal","subtypes":["aquatic"],"init":8,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+4 Dex, +3 natural, -1 size","hp":39,"hd":"6d8+12","hdvalue":6,"fort":7,"ref":9,"will":3,"defensive_abilities":["all-around vision"],"immunities":["flanks"],"speed":[{"type":"swim","speed":60}],"melee":"bite +7 (1d8+3 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"ambush"},{"type":"swallow whole","details":"1d4 acid damage, AC 11, 3 hp"}],"strength":15,"dexterity":18,"constitution":15,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":4,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":14},{"skill":"Swim","value":18}],"environments":["any aquatic"],"organizations":["solitary","school (2-4)"],"treasure":"none","description_visual":"This fish is long and slender with light spots along its body and a toothfilled maw.","group":"Pike","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ambush","kind":"Ex","details":"If a giant pike surprises an opponent, it gains a +4 circumstance bonus to its attack roll in that round of combat."}],"description":"Giant pikes are highly aggressive predators swimming the waters of freshwater lakes and rivers, attacking any living, moving creatures that come nearby. Giant pikes are highly adaptable and can be found in the coldest to the warmest waters. A saltwater variety exists and can be found in inland seas and saltwater lakes and rivers.\n\nGiant pikes, like their smaller counterparts, are voracious and often attack prey much larger than themselves. Their diet consists mainly of soft-finned fish, trout, perch, frogs, mice, ducks, birds, and small humanoids. Larger prey includes humanoids, other giant fish, deer, and sheep or goats. Giant pikes have no qualms about eating those of their own kind, especially when food is scarce.\n\nThe giant pike averages about nine ft. long and can grow to a length of 20 ft. Its coloration varies from dark green to brown and its body is covered in lighter colored spots. It has a single dorsal fin and a white or cream-colored underbelly.\n\nThe giant pike hides in weeds, behind rocks, or some other such cover, waiting for potential prey to wander nearby. It coils its body into an \"S\" position, and when prey passes by, strikes with blinding speed, biting with its sharp teeth. If the pike gets a hold on prey smaller than itself, it swallows it.","ecology":"","habitat_society":""},{"name":"Giant Slicer Beetle","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":1,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20}],"melee":"type +8 (2d8+9/19-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"vorpal bite"}],"strength":23,"dexterity":10,"constitution":16,"wisdom":10,"charisma":9,"baseatk":3,"cmb":10,"cmd":20,"cmd_special":"+8 vs. trip","feats":[{"feat":"Improved Critical (bite)","type":"bonus"}],"environments":["temperate forests"],"organizations":["solitary","cluster (2-5)"],"treasure":"incidental","description_visual":"This creature appears as a giant beetle with a triangular head and two long, razor sharp mandibles. Its body is black in color.","group":"Beetle","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Vorpal Bite","kind":"Ex","details":"The mandibles of a slicer beetle are extremely sharp. It gains Improved Critical (bite) as a bonus feat. The mandibles can sever body parts from opponents. If a slicer beetle scores a natural 20 on its attack roll and confirms the critical hit, it severs one of the opponent's extremities (roll 1d6: 1-3 arm, 4-6 leg; 50% chance of either right or left)."}],"description":"The slicer beetle closely resembles a large stag beetle and is often mistaken for such. However, the slicer beetle is more aggressive than the stag beetle. The creature dines on carrion, fresh meat, and leaves.\n\nStag beetles are about 10 ft. long, but can grow to lengths of 20 ft. or more.\n\nThe slicer beetle attacks by biting with its mandibles. A critical hit by the slicer beetle has a chance of severing a foe's arm or leg.","ecology":"","habitat_society":"","credit":"The Slicer Beetle originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Giant Tuatara","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+1 Dex, +5 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":10,"ref":7,"will":2,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"bite +7 (1d8+7)","space":"10 ft.","reach":"5 ft.","strength":21,"dexterity":13,"constitution":19,"intelligence":2,"wisdom":12,"charisma":2,"baseatk":3,"cmb":9,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Climb","value":9},{"skill":"Perception","value":8},{"skill":"Stealth","value":1},{"skill":"Swim","value":9}],"environments":["temperate hills","temperate plains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This reptile has a beak like upper jaw, a long narrow body and is covered in hard scales and short spines running along its back.","group":"Tuatara","source":"Tome of Horrors Complete (3pp)","description":"This burrowing reptile has a sharp beak designed to crack and tear through the carapace or scaled hide of its prey. A tuatara's diet consists of anything it can find: plants, insects, and adventurers. Prey that isn't devoured immediately is dragged back to its lair and either fed to the young. Their slow metabolism allows them to go long periods of time without eating so food is generally not kept or saved. In times when food is scarce, tuataras often eat their own kind.\n\nThey generally bury their eggs in a burrow with females producing 1d0+4 eggs per litter during the warmer months of the year. Females mate once about every four or five years, and rarely before 20 years of age (tuataras have a slow metabolism and don't reach maturity until about 20 years of age). Mating occurs in the early spring months and incubation lasts 13 to 15 months with young being born the following summer.\n\nYoung are helpless and depend solely on their mother for survival for the first few months of their life. Tuataras live to be about 100 years old.\n\nA giant tuatara is about ten ft. long and weighs close to 400 pounds.\n\nIts color ranges from gray or olive to dull red. It lacks ears but has two small openings on either side of its head that seem to function as such. On top of its head is a \"third eye\" (or parietal eye) that helps the tuatara in regulating its body temperature. Males have a noticeable crest down the center of its neck and back; females have the same crest, but it is much less pronounced.\n\nTuataras stalk their prey at night, having excellent vision in low light and a keen sense of smell. They generally avoid contact with creatures larger than themselves if they can help it. When threatened, a tuatara inflates its body, raises and flares its crest, and darkens the scales between its shoulders and neck.","ecology":"","habitat_society":""}];
